def strip_comments(text):
    result = []
    depth = pos = 0
    while pos < len(text):
        if text.startswith('(*', pos) and not text.startswith('(*)', pos):
            depth += 1
            pos += 2
        elif depth and text.startswith('*)', pos):
            depth -= 1
            pos += 2
        else:
            if not depth:
                result.append(text[pos])
            pos += 1
    need(depth == 0, 'complete nested Why3 comments')
    return ''.join(result)


